        const curUrl = mcpSession?.currentUrl || currentPageUrl || '';
        const urlOk = urlPattern ? mcp.matchUrlPattern(urlPattern, curUrl).matched : false;
        const probed = operationSnapshotProbe({ kind: 'page_ready', snapshotText: snap, expected, target });
