          stepIndex: trailEntry ? stepIndexFromTrail(trailEntry) : currentStepIndex,
          intent: expected,
          toolName,
          targetLabel: target || toolArgs.element || toolArgs.label || null,
          intendedValue: null,
          actualValue: curUrl,
          matched,
          evidenceSource: urlOk ? 'url_readback' : 'page_ready_probe',
          locatorQuality: widgetExecutionKernel.inferLocatorQuality(trailEntry || {}),
          reason: matched ? 'nav_or_logout_confirmed' : 'nav_or_logout_uncheckable',
          detail: urlPattern ? `url pattern ${urlPattern}` : null,
