    const stepOrdinal = (Number.isFinite(Number(trailEntry?.stepIndex)) ? Number(trailEntry.stepIndex) + 1 : currentStepIndex + 1);
    const assertion = `step:${stepOrdinal}:${value.slice(0, 80)}`;
