        channel: patch.channel || null,
        assertion: patch.assertion || null,
        synthetic: true,
        contractStepId: trailEntry.contractStepId || contractNode?.contractStepId || null,
        rowCoordinateId: trailEntry.rowCoordinateId || contractNode?.rowCoordinateId || null,
        dataBinding: contract.dataBinding || cloneContractPayload(trailEntry.dataBinding || { isDataBound: false }),
